import { cx } from '~/lib/cx'
import styles from './progress.module.scss'

export type ProgressSize = 'sm' | 'md' | 'lg'
export type ProgressTone = 'primary' | 'success' | 'warning' | 'destructive'

const SIZE: Record<ProgressSize, string> = {
  sm: styles.sm,
  md: '',
  lg: styles.lg,
}

const TONE: Record<ProgressTone, string> = {
  primary: '',
  success: styles.success,
  warning: styles.warning,
  destructive: styles.destructive,
}

export interface ProgressProps {
  /** 0–100. Omit to render an indeterminate bar. */
  value?: number
  size?: ProgressSize
  tone?: ProgressTone
  label?: string
  showValue?: boolean
  className?: string
}

export function Progress({
  value,
  size = 'md',
  tone = 'primary',
  label,
  showValue = true,
  className,
}: ProgressProps) {
  const indeterminate = value === undefined
  const clamped = indeterminate ? 0 : Math.min(100, Math.max(0, value))
  const rounded = Math.round(clamped)

  return (
    <div className={cx(styles.root, SIZE[size], className)}>
      {label ? (
        <div className={styles.header}>
          <span className={styles.label}>{label}</span>
          {!indeterminate && showValue ? (
            <span className={styles.value}>{rounded}%</span>
          ) : null}
        </div>
      ) : null}

      <div
        role="progressbar"
        aria-label={label ?? 'Progress'}
        aria-valuemin={indeterminate ? undefined : 0}
        aria-valuemax={indeterminate ? undefined : 100}
        aria-valuenow={indeterminate ? undefined : rounded}
        aria-valuetext={indeterminate ? undefined : `${rounded}%`}
        className={cx(styles.track, TONE[tone])}
      >
        <div
          className={cx(styles.indicator, indeterminate && styles.indeterminate)}
          style={indeterminate ? undefined : { width: `${clamped}%` }}
        />
      </div>
    </div>
  )
}

@use 'styles' as vz;

.root {
  --progress-height: #{vz.space(2)};
  --progress-bg: #{vz.color('primary')};

  display: flex;
  flex-direction: column;
  gap: vz.space(2);
  width: 100%;
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: vz.space(3);
  font-size: vz.font-size('sm');
}

.label {
  color: vz.color('foreground');
  font-weight: 500;
}

.value {
  color: vz.color('muted-foreground');
  font-variant-numeric: tabular-nums;
}

.track {
  position: relative;
  width: 100%;
  height: var(--progress-height);
  overflow: hidden;
  border-radius: vz.radius('full');
  background: vz.color('muted');
}

.sm {
  --progress-height: #{vz.space(1)};
}

.lg {
  --progress-height: #{vz.space(3)};
}

.indicator {
  height: 100%;
  border-radius: inherit;
  background: var(--progress-bg);
  transition: width vz.duration('slow') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.success {
  --progress-bg: #{vz.color('success')};
}

.warning {
  --progress-bg: #{vz.color('warning')};
}

.destructive {
  --progress-bg: #{vz.color('destructive')};
}

.indeterminate {
  width: 35%;
  animation: vz-progress 1.4s vz.ease('in-out') infinite;

  @include vz.motion-reduce {
    animation: none;
    width: 100%;
    opacity: 0.4;
  }
}

@keyframes vz-progress {
  0% {
    transform: translateX(-100%);
  }

  100% {
    transform: translateX(320%);
  }
}
